# -*- coding: utf-8 -*-
"""English translations, batch 5 (40 figures)."""
EN = {
"约拿单的儿子米非波设": dict(lesson="Grace receives the most unworthy",
 summary="Jonathan's disabled son; for the sake of his covenant with Jonathan, David sought him out and let him eat at the king's table like a prince.",
 witness="Mephibosheth said: who am I, but a dead dog? Yet David said: you shall always eat at my table. This is a picture of grace—not because he deserved it, but because of the covenant. It is exactly the picture of God toward us.",
 follow=["Calling himself a 'dead dog,' yet humbly receiving David's free grace, daily dining with the king like a prince (2 Sam 9:8)—a living picture of a sinner shown mercy","Not defending himself when Ziba slandered him and his estate was seized","After David returned, saying 'let the king come home in peace; let Ziba take it all'—valuing the relationship with the king above the estate (2 Sam 19:30)"],
 caution=[],
 applications=["What is your posture in receiving God's grace?","Do you think yourself worthy of God's table?","Grace is because of the covenant (Jesus' cross), not because of your merit"],
 prayer="Lord, Mephibosheth thought himself a dead dog, yet You seated him at the king's table. Thank You for receiving me because of Your covenant. Help me sit humbly at Your table. Amen."),
"所罗门后期": dict(lesson="Wisdom cannot protect a disobedient heart",
 summary="In his later years Solomon turned from God through his many foreign wives, his heart divided—the case of the greatest wisdom defeated by the smallest temptation.",
 witness="He had the greatest wisdom and wrote of Ecclesiastes' vanity, yet was gradually drawn from God by women and comfort. God appeared to him twice, and still he strayed. This tells us: wisdom itself cannot replace obedience; knowledge without commitment is dangerous.",
 follow=[],
 caution=["Letting intimate relationships gradually erode his faith stance","Replacing obedience to God with God's gift (wisdom)","A divided heart, wavering between God and idols"],
 applications=["What 'good thing' in your life is slowly drawing you from God?","Wisdom without obedience is dangerous","You most need watchfulness when most comfortable"],
 prayer="Lord, Solomon's end warns me: the greatest gift cannot guarantee final faithfulness. Help me not only be clever, but truly obey You. Amen."),
"耶洗别": dict(lesson="The spiritual danger of control and manipulation",
 summary="Queen of the north who aggressively promoted Baal worship, killed the prophets, and manipulated King Ahab—Scripture's most typical case of power manipulation and spiritual corruption.",
 witness="Jezebel never acted directly; she used manipulation, forged letters, and Ahab's power. She had Naboth killed and Baal flourish. Revelation uses her name to describe teaching that leads people from God. Manipulation is harder to detect than overt evil, and more dangerous.",
 follow=[],
 caution=["Achieving her ends through manipulation and control rather than direct, legitimate means","Promoting false worship under a religious cloak","Using the power of those close to her for her own ambition"],
 applications=["Examine: do I have Jezebel-like tendencies toward manipulation?","In relationships, do I influence or control?","Be discerning about manipulative influence within religion"],
 prayer="Lord, Jezebel's manipulation reminds me: influence can serve God or corrupt faith. Help me examine my motives and methods in influencing others. Amen."),
"巴拿巴": dict(lesson="The gift of encouragement fulfilling others' callings",
 summary="Called the son of encouragement; he sold a field and gave the proceeds, received the newly repentant Saul, discovered Paul, and gladly stepped back to the second line to advance others.",
 witness="When everyone doubted Paul, Barnabas brought him to the apostles, vouching for him with his own reputation. Later Paul's mission surpassed his; he did not envy, but gladly paved the way for Paul. The best leaders raise up people better than themselves.",
 follow=["Actively receiving and supporting one whom others doubted","Gladly stepping to second place to advance others","Making giving concrete: selling a field for the church's need"],
 caution=[],
 applications=["Do you have a 'Paul' you can encourage and help?","Encouragement is one of the kingdom's most important gifts","Advance someone more gifted than you—this is the greatest act of leadership"],
 prayer="Lord, Barnabas used his reputation to help Paul, then gladly stepped back. Help me too be willing to advance those more gifted than me, rather than guard my position. Amen."),
"十字架上的强盗": dict(lesson="Last-moment repentance is also received by God",
 summary="On the cross, a robber pleaded with Jesus in life's final moment: remember me when You come into Your kingdom. Jesus answered: today you will be with Me in paradise.",
 witness="He had no time to do any good work, no chance to be baptized, no chance to make restitution. He had only one cry: remember me. Jesus said: today—not later, not after you've done something—today you will be with Me in paradise. This is the most thorough grace.",
 follow=["In life's last moment still testifying to Jesus' innocence: 'this man has done nothing wrong' (Luke 23:41)","Humbly asking 'remember me when You come into Your kingdom,' seizing the last window of grace (Luke 23:42)","Proving salvation depends on faith, not works—'today you will be with Me in paradise'"],
 caution=[],
 applications=["For the person hardest for you to evangelize: there is still hope at the last moment","No time is too late to turn to Jesus","Repentance does not require changing first and then coming; come first, then be changed"],
 prayer="Lord, You said 'today' to that robber. This is the most thorough grace—not later, not after I clean up. Thank You for receiving even the one who repents at the last moment. Amen."),
"抹大拉的马利亚": dict(lesson="The freed becomes the most faithful witness",
 summary="Seven demons were driven out of her; thereafter she followed Jesus, was present at the cross and the empty tomb, and was the first witness of the resurrection.",
 witness="She was present at Jesus' loneliest moments—at the cross, by the tomb. On resurrection morning she came seeking Jesus, and He called her name: Mary. In that moment of being named, she recognized Him. The one changed by love is the most faithful witness.",
 follow=["Having seven demons cast out and being freed, she faithfully followed and supported the Lord with her means all her life (Luke 8:2-3)","When the disciples scattered, she stayed at the cross and by the tomb, loving to the end without leaving (John 19:25; 20:1)","Becoming the first witness of the resurrection, sent by the Lord Himself to bring the news (John 20:17-18)"],
 caution=[],
 applications=["Your once-deepest bondage can become the most powerful witness","When everyone else leaves, where are you?","Jesus knows your name; let Him call it today"],
 prayer="Lord, You called Mary's name, and she instantly recognized You. Thank You that You know my name too. Help me be a faithful witness of Your resurrection like her. Amen."),
"司提反": dict(lesson="The witness of martyrdom for the faith",
 summary="The first martyr; as he was stoned, he saw heaven open and the Son of Man standing at God's right hand, prayed for his enemies as he died, and indirectly influenced Saul's conversion.",
 witness="As they stoned him, he knelt and cried out: Lord, do not hold this sin against them. Then he fell asleep. That prayer may have been the first thread in Paul's journey to the Lord. One man's death changed another man's direction, affecting the whole Gentile world.",
 follow=["Facing the most extreme persecution filled with the Spirit","Praying for his enemies as he died","His witness influencing beyond his death"],
 caution=[],
 applications=["Praying for persecutors amid persecution is the hardest and most powerful witness","Your faithfulness today may be shaping a future 'Paul'","Pray for those now persecuting Christians"],
 prayer="Lord, Stephen prayed for his enemies as he died. Help me, when wronged or suffering, still pray for those who hurt me, trusting You can use my witness. Amen."),
"约伯的妻子": dict(lesson="Despair and giving up in suffering",
 summary="In Job's deepest suffering, his wife said to him: curse God and die—the most extreme cry of despair in a crisis of faith.",
 witness="Her words come at the depth of Job's suffering. We don't know her full story—she too lost her children, she too suffered. But her response was a despairing surrender. Suffering can make one curse faith, or grasp God more deeply. Job rejected her advice.",
 follow=[],
 caution=["Telling someone to give up God at the depth of suffering","Treating death as an exit from suffering","Despair becoming a danger to another's faith"],
 applications=["In suffering, are you Job or Job's wife?","Are your words support or a stumbling block at another's weakest?","How can a community in suffering build one another up rather than tear down?"],
 prayer="Lord, Job rejected the advice of despair and still trusted You. Help me not give up on You in the deepest suffering, and let my words be a pillar to others' faith, not a stumbling block. Amen."),
"以利法、比勒达、琐法": dict(lesson="Wrong comfort hurts more than silence",
 summary="Job's three friends, who at first sat with him in silence for seven days, then blamed Job with mistaken theology; God finally said they had spoken wrongly.",
 witness="Their best moment was the first seven days: sitting on the ground in silence, seeing his suffering was very great. Then they spoke, explaining suffering with 'you must have sinned.' God said: you have not spoken of Me rightly, as My servant Job has. Knowledge without humility hurts more than it helps.",
 follow=[],
 caution=["Explaining another's suffering with theological theory rather than empathy","Blaming the sufferer with 'it must be your sin'","Hurting more by speaking than by silence"],
 applications=["Accompany the suffering: first be present in silence, then speak carefully","For suffering you don't understand, stay humble rather than explain","Is there someone who needs you to quietly sit with them today?"],
 prayer="Lord, the three friends' first seven days were the best accompaniment; then they spoke. Help me be present in silence first when others suffer, not rushing to explain. Amen."),
"基甸的三百人": dict(lesson="God can win with few against many",
 summary="God reduced Gideon's army from thirty-two thousand to three hundred, then defeated the great Midianite army with trumpets and clay jars.",
 witness="God said: there are too many; I cannot give Midian into their hands. Then He cut and cut again, down to three hundred. These three hundred did not shrink because of small numbers; their weapons were trumpets and jars, not swords. God wants not your ability, but your obedience.",
 follow=["The great army cut by God to only three hundred, yet still obeying and going to battle, not relying on numbers (Judg 7:7)","Gladly using God's 'unconventional weapons'—trumpet blasts, empty jars, torches—to fight, so all the victory went to God (Judg 7:20)"],
 caution=[],
 applications=["Do you feel your strength is too small? God may be reducing it so you rely on Him","What 'trumpet' has God put in your hand?","Trust that God can give victory at the most unlikely moment"],
 prayer="Lord, three hundred defeated a great army. Help me not be discouraged by reduced strength, but rely on You all the more. Amen."),
"约阿施": dict(lesson="Spiritual growth needs continuous spiritual guidance",
 summary="Protected in the temple as a child, he did right under the priest Jehoiada's mentoring, but after Jehoiada died he turned to corruption, even killing Jehoiada's son Zechariah.",
 witness="He did right in God's eyes under Jehoiada's protection and mentoring. When Jehoiada died, he turned at once. This shows spiritual life must truly be internalized, not merely depend on outside mentoring. Relying on spiritual authority rather than real commitment to God collapses when that person is gone.",
 follow=["As a child, protected by the priest Jehoiada from being killed; grown, doing what was right in the LORD's eyes","Zealously repairing the broken-down temple, doing real good for the people (2 Kgs 12)"],
 caution=["A spiritual life depending on a mentor more than on God Himself, rooted in a person","Turning to corruption right after his spiritual mentor Jehoiada died, following officials into idolatry","In revenge against the prophet who admonished him, ordering the murder of his benefactor Jehoiada's son Zechariah (2 Chr 24:20-22)"],
 applications=["Is your faith your own, or dependent on someone?","Spiritual mentors matter, but cannot replace your personal relationship with God","If your most trusted spiritual mentor disappeared, would your faith remain?"],
 prayer="Lord, Joash's tragedy was that his faith was borrowed. Help my faith be truly my own—deep within, not propped up by anyone's presence. Amen."),
"拿俄米": dict(lesson="Honesty in suffering and the surprise of grace",
 summary="A widow who lost her husband and two sons, so bitter she had people call her 'Bitter,' yet became the bridge to Ruth's faith and Boaz's in-law.",
 witness="She said: do not call me Naomi, call me Mara (bitter), for the Almighty has dealt very bitterly with me. This is one of Scripture's most honest faith statements. She did not pretend all was well, yet God still worked in her bitterness. Honest grief is the start of restoration.",
 follow=["Honestly expressing God's dealings in suffering, not hiding her pain","Amid the agony of losing husband and sons, still guiding Ruth toward the God and inheritance of Israel (Ruth)","Actively planning a home for Ruth, becoming a bridge to the next generation's faith and marriage"],
 caution=["Once falling into self-pity, asking to be called 'Mara (bitter),' attributing her plight solely to 'the Almighty has dealt bitterly with me'","At first urging both daughters-in-law to return to Moab, nearly causing Ruth to miss the blessing of joining God's people"],
 applications=["Do you allow yourself to honestly say to God 'I am bitter'?","God was still working in Naomi's bitterness","The suffering in your life can become a bridge to another's faith"],
 prayer="Lord, Naomi honestly said: You have dealt bitterly with me. Thank You for not requiring me to pretend all is well. Help me still see Your work in honest bitterness. Amen."),
"彼得岳母": dict(lesson="Serving at once after being healed",
 summary="Peter's mother-in-law was healed of a fever by Jesus and rose at once to serve everyone—the most concise picture of 'serving immediately after being healed.'",
 witness="Jesus took her hand, and she rose at once to serve everyone. No rest, no hesitation. The natural response of one touched by grace is to serve. This is faith's simplest cycle: receive grace → rise → serve.",
 follow=["As soon as the fever left, she 'rose and served them,' her first response to healing being service, not rest (Mark 1:31)","Serving without waiting for full recovery or perfect conditions, turning received grace into action at once"],
 caution=[],
 applications=["What grace from God have you recently received? What is your response?","The healed make the best servers","Rise today and serve with what you already have"],
 prayer="Lord, Peter's mother-in-law was healed and at once served. Help me not keep Your grace to myself, but let it turn at once into service to others. Amen."),
"安得烈": dict(lesson="The ministry of bringing people to Jesus",
 summary="Peter's brother; his first act was to find Peter and say, we have found the Messiah, then bring him to Jesus.",
 witness="Andrew was not the most famous apostle; Peter was more renowned. But Peter came to Jesus because Andrew brought him. The boy's five loaves and two fish—Andrew brought him. The Gentiles wanting to see Jesus—Andrew and Philip reported it. He is always 'bringing people to Jesus.'",
 follow=["His first act on meeting Jesus was to find his brother Simon: 'we have found the Messiah,' bringing his own kin to the Lord (John 1:41)","Gladly staying behind the scenes—bringing the boy with five loaves and two fish, bringing the Greeks to Jesus, always introducing others without grasping the spotlight (John 6:8; 12:22)","Reminding us: the small thing of 'bringing people to Jesus' may bear history-changing fruit (the Peter he brought)"],
 caution=[],
 applications=["Whom have you recently brought to Jesus?","Andrew-style ministry: not the stage, but the guiding","Invite someone to church or share your faith today"],
 prayer="Lord, every time Andrew appears, he is bringing people to You. Help me be such a person too: needing no stage, only bringing people to Jesus. Amen."),
"多马": dict(lesson="From doubt to the deepest confession of faith",
 summary="Called Doubting Thomas, but also the first disciple to say 'My Lord and my God' before the risen Jesus.",
 witness="He said: unless I see with my eyes and touch with my hands, I will not believe. Jesus did not refuse him, but appeared specially for him. Then Thomas made the deepest confession in Scripture: my Lord and my God. The deepest doubt can produce the deepest faith.",
 follow=["Making the deepest confession of faith after the deepest doubt","Willing to express his doubt before Jesus"],
 caution=["Making 'seeing with my own eyes' a condition of faith"],
 applications=["Do you have Thomas-like doubt? Bring it to Jesus","Doubt is not faith's end, but can be the start of its deepening","What is your most honest confession to Jesus today?"],
 prayer="Lord, Thomas' doubt yielded the deepest confession: my Lord and my God. Help me bring all my doubts to You too, letting them become an occasion to know You more deeply. Amen."),
"革妈利": dict(lesson="Wisdom to discern God's work",
 summary="A Pharisee and teacher of the law in the Sanhedrin, who at the apostles' trial advised: if it is of man, it will fail; if it is of God, you cannot stop them.",
 witness="He was Paul's teacher and a strict Pharisee, yet at the most important moment he spoke the wisest words. He did not believe, but he admitted he could not judge God's work. Sometimes the greatest wisdom is to say: I don't know; I'll wait and see.",
 follow=["When the council was enraged and wanted to kill the apostles, calmly advising 'if it is of God, you cannot overthrow them, lest you be found opposing God' (Acts 5:38-39)","Knowing how to discern what is man's work and what may be God's, not jumping to dogmatic conclusions"],
 caution=[],
 applications=["For work outside the church, can you observe first rather than condemn at once?","Humbly admit your own limits","'Wait and see'—sometimes the wisest stance"],
 prayer="Lord, Gamaliel's wisdom was to say: if it is of God, you cannot stop them. Help me, facing uncertain matters, have the wisdom to wait humbly. Amen."),
"腓利门": dict(lesson="Forgiveness transcends social structures",
 summary="Paul's friend; Paul wrote asking him to take back the runaway slave Onesimus, no longer treating him as a slave but receiving him as a brother.",
 witness="Paul said: if you consider me a partner, receive him as you would receive me. This is a letter asking a man of power to give up power to receive. Philemon, by accepting the letter, had already chosen to accept this request. True forgiveness changes the nature of a relationship.",
 follow=["At Paul's urging, willing to receive the runaway Onesimus 'no longer as a slave, but as a beloved brother' (Philem 16)","Redefining the relationship by the gospel—forgiving one who had wronged him, receiving him into brotherly love"],
 caution=[],
 applications=["Is there someone you need to receive with a new identity?","True forgiveness changes the nature of your relationship with that person","Is there a 'Philemon letter' you need to respond to today?"],
 prayer="Lord, Paul asked Philemon to receive Onesimus as himself. Help me too receive one who once hurt me, no longer defining them by their old identity. Amen."),
"百基拉与亚居拉": dict(lesson="A couple serving together in one heart",
 summary="A tentmaking couple who hosted Paul in various places, opened their home as a church, and privately taught Apollos—a model couple serving the kingdom.",
 witness="They were not elders, had no important title; they were tentmakers. But every time they appear, they are serving the gospel—opening their home as a church, privately teaching the gifted but doctrinally incomplete Apollos. Their home was a tool of the kingdom.",
 follow=["Opening their tent workshop and home as a 'house church' for hosting Paul and gatherings (1 Cor 16:19)","Hearing gaps in Apollos' preaching, privately taking him in to 'explain the way of God more accurately,' gently supplementing without public shaming (Acts 18:26)","Serving together in one heart, even 'risking their necks' for Paul, thanked by all the churches (Rom 16:4)"],
 caution=[],
 applications=["Can your home become a tool of the kingdom?","Gentle, private correction is more effective than public rebuke","A couple serving together is the most powerful family witness"],
 prayer="Lord, Priscilla and Aquila turned their home into a kingdom tool. Help me too be willing to open all I have to serve Your kingdom. Amen."),
"雅各（耶稣兄弟）": dict(lesson="Transformation from unbelief to leader",
 summary="Jesus' brother, who did not believe in Jesus before the resurrection, met Him after, became leader of the Jerusalem church, wrote the Epistle of James, and was martyred.",
 witness="During Jesus' ministry he was among the family of whom it was said 'even his brothers did not believe in him.' Then Jesus rose and appeared specially to him (1 Cor 15:7). He went on to become a pillar of the Jerusalem church. Even the most familiar relationship can become the deepest faith relationship.",
 follow=["Not believing in his brother before the resurrection, utterly transformed by the Lord's appearance after, becoming a pillar of the Jerusalem church (1 Cor 15:7; Gal 2:9)","Calling himself 'a servant of the Lord Jesus Christ,' humbly serving the elder brother he grew up with (Jas 1:1)","Writing the Epistle of James, stressing 'faith without works is dead,' grounding faith in practice (Jas 2:17)"],
 caution=[],
 applications=["Those who know you best sometimes find it hardest to accept your faith","Unbelief among family is not the end","Pray for your unbelieving family today"],
 prayer="Lord, James went from unbelief to becoming a church pillar. Help me keep praying for my unbelieving family, trusting You will work in them too. Amen."),
"拿因城的寡妇": dict(lesson="Jesus actively shows compassion to the grieving",
 summary="At the funeral of a widow's only son in the small town of Nain, Jesus, uninvited, stopped of His own accord, had compassion on her, and raised her son from the dead.",
 witness="When Jesus saw her, He had compassion and said: do not weep. He was not invited; no one had asked Him. He stopped on His own, because He 'saw' her. God sees your deepest grief, even when you have not spoken a word of plea.",
 follow=["At her only son's funeral, still walking on the road where she could meet Jesus—not leaving the community of God's presence in her despair","Quietly receiving the Lord's uninvited compassion and rescue, not resisting grace (Luke 7:13-15)"],
 caution=[],
 applications=["God sees you in your deepest grief too","Don't think you must speak first before God acts","Bring your deepest grief to Jesus today"],
 prayer="Lord, uninvited, You stopped of Your own accord to have compassion on that widow. Thank You that You saw my tears before I even spoke. Amen."),
"西门（古利奈人）": dict(lesson="A cross forced upon him becomes a spiritual calling",
 summary="A man coming into the city from the country, forced by Roman soldiers to help Jesus carry the cross; his sons Alexander and Rufus later became members of the church.",
 witness="He was forced, not willing. Coming into the city from the country, he was randomly seized to carry the cross. But his two sons Alexander and Rufus later became believers (named by Mark, showing the readers knew them). A forced act changed a family's spiritual history.",
 follow=["Forced by Roman soldiers to carry the cross, yet from that forced burden became the truest living picture of 'take up your cross and follow Me' (Mark 15:21)","This encounter evidently changed the whole family—sons Alexander and Rufus later became believers known to the church (Rom 16:13)"],
 caution=[],
 applications=["Some forced experiences hold God's plan","The burden forced upon you may be your life's greatest turning point","Give to God the thing you don't want to carry today, and see what happens"],
 prayer="Lord, Simon was forced to carry the cross, yet thereby became part of history. Help me accept forced burdens, trusting You can turn them around in unexpected ways. Amen."),
"拿单先知": dict(lesson="The courage to speak truth with wisdom",
 summary="David's prophet, who conveyed God's promise of building the temple, and after David's sin pointed it out with a parable—a model prophet of speaking truth.",
 witness="David was king, Nathan a prophet. Nathan did not say directly: you have sinned. He told a story: a rich man took a poor man's lamb. David was furious, and Nathan said: you are the man. Wisdom is speaking truth in a way that lets a person see it for himself.",
 follow=["Using the parable of 'the rich man taking the poor man's lamb' to let David condemn himself, then revealing 'you are the man'—speaking truth by wisdom rather than confrontation (2 Sam 12:1-7)","Risking offending the king, still bringing God's rebuke faithfully to David","Also faithfully conveying God's covenant of grace to David, 'your house and your kingdom shall be established forever'—bringing both good news and hard (2 Sam 7:16)"],
 caution=[],
 applications=["Is there a truth you need to speak with wisdom?","How can you speak so a person receives rather than defends?","Pray for leaders who need to hear the truth"],
 prayer="Lord, Nathan spoke truth to David with wisdom and courage. Help me, when I must speak truth, say it wisely—not to please, not to wound, but to speak God's words. Amen."),
"乌西雅": dict(lesson="Pride is most dangerous at the peak of success",
 summary="A king of Judah who did right in God's eyes in his first half and built the nation's strength, but at the peak of power presumptuously entered the temple to burn incense and was struck with leprosy for his pride.",
 witness="A successful first half: he sought God, and God made him prosper. 2 Chr 26:5 says: as long as he sought the LORD, God made him prosper. Then everything changed—his heart grew proud. Pride's most dangerous moment is not in failure, but at the peak of success. He did not turn bad overnight, but gradually.",
 follow=[],
 caution=["Falling into pride at his most successful","Crossing the boundary God set: presumptuously entering the temple","Not heeding the priests' correction, but growing angry instead"],
 applications=["Is your most successful area lately also a danger zone for pride?","In success you need to seek God all the more humbly","Is there any 'boundary-crossing' behavior in your life?"],
 prayer="Lord, Uzziah grew proud at his most successful, then fell. Help me seek You all the more humbly in success, not replacing reliance with achievement. Amen."),
"约西亚": dict(lesson="Humility before God's word brings revival",
 summary="A king of Judah who took the throne at eight; when the Book of the Law was found during temple repairs, he immediately tore his clothes in confession and led the whole nation to covenant and return to God—history's most thorough religious reform.",
 witness="They found the Book of the Law and read it to him, and he immediately tore his clothes. This was a king's humble response—not arguing, not explaining, but confessing. Then he gathered everyone and personally read the law before them, covenanting together. Humbly hearing God's word is the start of revival.",
 follow=["Hearing the long-neglected Book of the Law read, immediately tearing his clothes, grieving and humbling himself before God (2 Kgs 22:11)","Not only repenting himself, but leading the whole nation to covenant and thoroughly remove idols—history's most thorough reform (2 Kgs 23:3)","Taking the throne at eight, young yet 'doing right in the LORD's eyes, not turning aside to the right or left' (2 Chr 34:2)"],
 caution=[],
 applications=["When were you last 'pierced' by God's word?","A humble response to God's word is the key to revival","Read Scripture systematically today, giving God's word a chance to speak"],
 prayer="Lord, Josiah tore his clothes when he heard Your word. Help me come to Your word with such a humble heart, letting it truly change me and those around me. Amen."),
"押沙龙": dict(lesson="Power built on charm and bitterness must collapse",
 summary="David's son who, after his father failed to act when his sister Tamar was raped, grew bitter, finally won people's hearts with charm, launched a coup, and perished in a forest.",
 witness="He stood at the city gate helping those who came with complaints, saying: your case is good, but no one will hear you—stealing hearts with premeditated, charming politics. Unaddressed bitterness turned into political manipulation. Charm and charm-politics both got caught by a tree branch in the end.",
 follow=[],
 caution=["Letting bitterness ferment in his heart for years without addressing it","Stealing the legitimate path to power with charm and popular favor","Taking vengeful action in resentment over his father's sin"],
 applications=["Is there bitterness in your heart unaddressed for years?","Charm can build influence, or become a tool of manipulation","Deal with the bitterness in your heart before God today"],
 prayer="Lord, Absalom's bitterness destroyed himself and his family. Help me address the bitterness in my heart today, not letting it ferment in the dark into greater destruction. Amen."),
"俄巴底亚": dict(lesson="Secretly protecting God's servants in danger",
 summary="Steward of King Ahab's house, who secretly hid a hundred prophets, protecting them from Jezebel's slaughter—a secret guardian in a dark age.",
 witness="When Jezebel killed the prophets, Obadiah hid a hundred in caves, supplying them food and water. He did not openly resist; he did what he could from his position. Not all courage is public proclamation—some courage is quiet protection.",
 follow=["'Greatly feared the LORD,' risking his life to hide a hundred prophets in caves and supply them bread and water during Jezebel's slaughter (1 Kgs 18:3-4)","Holding high office under Ahab's evil rule, yet using his position to secretly protect God's servants"],
 caution=[],
 applications=["What can your position let you do to protect the vulnerable?","Not all service needs to be in the spotlight","Is there someone who needs your quiet protection or help today?"],
 prayer="Lord, Obadiah quietly protected a hundred prophets. Help me too be willing to use my position to quietly serve and protect those who need help. Amen."),
"以利亚的仆人": dict(lesson="Keep waiting until God's promise comes true",
 summary="After Elijah prayed for rain on Mount Carmel, he sent his servant seven times to look at the sea; the servant reported back each time, until the seventh time he saw a small cloud.",
 witness="Six times: nothing. The servant did not give up, Elijah did not stop praying. The seventh time: a cloud as small as a man's hand. Then a downpour. Faith's persistence: after six times of seeing nothing, still going the seventh time. The result began with one small cloud.",
 follow=["Sent to look at the sea, six times in a row 'nothing,' yet obediently going a seventh time, until he saw a cloud the size of a palm (1 Kgs 18:43-44)","Continuing to watch when the answer was not yet visible, not giving up on his own, trusting the one who sent him"],
 caution=[],
 applications=["How many times have you waited in prayer? Ready to go a seventh time?","A small cloud is the start of a downpour","Persist in prayer while waiting without seeing results"],
 prayer="Lord, that servant went seven times. Help me, after six times of seeing nothing, still have the faith to go a seventh time, for Your promise will surely come to pass. Amen."),
"撒母耳的母亲哈拿": dict(lesson="Pouring out to God and entrusting in suffering",
 summary="A barren woman who wept and prayed in the temple, vowing to give the child back to God; God heard her, she bore Samuel, and she kept her vow.",
 witness="She wept bitterly before God, pouring out the bitterness of her heart. The priest Eli thought she was drunk. She said: I have drunk no wine; I am pouring out my soul before the LORD in my distress. God heard the prayer of tears. She vowed: if You give me a child, I will give him back to You. And she truly did.",
 follow=["Honestly pouring out her deepest pain to God","Faithfully keeping her vow after making it","Singing a song of thanksgiving after receiving the answer"],
 caution=[],
 applications=["Do you allow yourself to weep before God?","Bring your deepest pain to God today","If God hears, how are you willing to respond to Him?"],
 prayer="Lord, Hannah wept before You, and You heard her tears. Help me too bring my deepest pain to You, trusting You see and hear. Amen."),
"喇合": dict(lesson="Faith that transcends background receives grace",
 summary="A prostitute of Jericho who hid the Israelite spies, marked by a scarlet cord; her whole household was saved, she joined Israel, and became an ancestor of David and Jesus.",
 witness="She said: I know the LORD has given you this land, and we are terrified of you. Her faith came from what she had heard. She was not an Israelite, she was a prostitute, but she believed, she acted, and her action was the witness of faith. Heb 11:31 says: Rahab did not perish with the disobedient, because she welcomed the spies.",
 follow=["Hearing what God did for Israel, responding in faith 'the LORD is God in heaven above and on earth below,' risking her life to hide the spies (Josh 2:11)","Marking her window with a scarlet cord, bringing her whole household into the covenant of salvation (Josh 2:18)","A prostitute's past not blocking God's grace—listed among the heroes of faith, and entering Jesus' genealogy (Heb 11:31; Matt 1:5)"],
 caution=[],
 applications=["Your past cannot limit what God will do in you","Faith without action is dead: Rahab hung the scarlet cord","God uses unexpected people, entering unexpected genealogies"],
 prayer="Lord, Rahab was a prostitute, yet entered Jesus' genealogy. Thank You for not defining my future by my background. Help me express my faith in action today. Amen."),
"耶罗波安": dict(lesson="Replacing God's will with political calculation",
 summary="The first king of the northern kingdom; God promised him a dynasty, yet for political reasons he set up golden calves and became known as 'Jeroboam who made Israel sin.'",
 witness="God gave him a promise, conditioned on obedience. He did not trust that people going to the temple would turn back to David's house, so he set a golden calf in Bethel and Dan, saying: O Israel, these are your gods who brought you out of Egypt. Political calculation defeated faithful obedience. His name became a pattern: of the twenty kings of the north, every one 'walked in the way of Jeroboam.'",
 follow=[],
 caution=["Replacing obedience to God with calculations of political stability","Rationalizing wrong behavior with religious language","Building an 'equally convenient' substitute faith system"],
 applications=["Have you built your own 'golden calf'—replacing true worship with a convenient substitute?","Political calculation is often the greatest obstacle to obeying God","Examine: in decisions, is God's will first, or my interest first?"],
 prayer="Lord, Jeroboam replaced obedience to You with political calculation. Help me not make convenience and stability my first consideration in decisions, but truly seek Your will. Amen."),
"亚波罗": dict(lesson="The combination of talent and humbly receiving correction",
 summary="An eloquent man from Alexandria, mighty in the Scriptures and fervent in preaching, who knew only John's baptism; after Priscilla and Aquila taught him privately, he became a more powerful preacher.",
 witness="He had talent, passion, and knowledge of Scripture—but incomplete. Priscilla and Aquila explained the way of God to him more accurately in private, and he accepted it. Talent plus humbly receiving correction is the most powerful combination. Talent without accepting correction is dangerous; humility without talent is limited. Both together is what the kingdom most needs.",
 follow=["Most learned, best at explaining Scripture, fervent in heart, boldly preaching what he knew (Acts 18:24-25)","Facing the private correction of Priscilla and Aquila, not defensive, but humbly receiving the more complete truth (Acts 18:26)","After being taught, more powerful, forcefully refuting opponents in public and greatly building up others (Acts 18:28)"],
 caution=[],
 applications=["Is there an 'incomplete' area in your faith knowledge that needs updating?","Has someone tried to correct you—do you defend or accept?","Talent is God-given; humility is your choice"],
 prayer="Lord, Apollos was brilliant yet humbly received correction. Help me serve fervently with the talents You gave, while keeping an open heart to receive more complete truth. Amen."),
"阿尼西母": dict(lesson="Transformation from runaway slave to useful brother",
 summary="Philemon's runaway slave who came to the Lord in Paul's prison; Paul called him 'my own heart,' and wrote asking Philemon to receive him as a brother.",
 witness="He went from a runaway, 'useless' slave to a co-worker Paul called 'useful.' His name means 'useful'—he finally lived up to his name. In Christ, your past identity no longer defines you; you can live out the meaning of your true name.",
 follow=["From a 'useless' runaway slave, after coming to the Lord in Paul's prison, becoming a 'profitable' man (Philem 11; the name means 'profitable')","Willing to return to the master he had wronged and fled from, facing rather than continuing to hide from the past"],
 caution=[],
 applications=["Is there a relationship or responsibility in your life you keep fleeing?","In Christ, your past no longer defines you","Do you need, like Onesimus, to go back and face something today?"],
 prayer="Lord, Onesimus went from useless to useful, from fleeing to returning. Help me too live out in You the life I was meant to have, no longer fleeing but facing. Amen."),
"提摩太": dict(lesson="Shaped into a faithful co-worker in weakness",
 summary="Paul's spiritual son, whose faith was nurtured by his grandmother Lois and mother Eunice; timid by nature, yet entrusted with heavy responsibility by Paul, experiencing growth and shaping.",
 witness="Paul said he had 'sincere faith,' first in his grandmother Lois and mother Eunice. The inheritance of faith begins in the family. Paul also said: share in suffering for the gospel with me. The weak too can be used by God—Paul reminded him: let no one despise your youth.",
 follow=["Inheriting the 'sincere faith' of his grandmother Lois and mother Eunice, knowing Scripture from childhood (2 Tim 1:5; 3:15)","Timid by nature and physically weak, yet reminded 'God gave us not a spirit of fear,' bravely shepherding in weakness (2 Tim 1:7)","Gladly being Paul's spiritual son and faithful co-worker, entrusted with hard ministries like Ephesus"],
 caution=[],
 applications=["From whom did you inherit your faith? Thank that person","Weakness is not a reason for not being used, but the starting point of relying on God","Is there something you haven't done because of weakness today?"],
 prayer="Lord, Timothy was weak yet faithful. Help me not use weakness as an excuse, but rely on Your strength in weakness to do what You call me to. Amen."),
"路司特的瘸腿人": dict(lesson="Faith makes a person stand and walk",
 summary="A man lame from birth who had never walked; Paul saw he had faith and said to him: stand up on your feet. And he leaped up and walked.",
 witness="Paul looked intently at him and saw he had faith to be healed. Faith is not invisible—others can see your faith. The man's faith showed in his posture of intently listening to Paul's preaching. He had never walked, yet leaped up at one word: stand up. God's word plus human faith produces a miracle.",
 follow=["Lame from birth, never having walked, yet generating 'faith to be healed' while listening to Paul preach (Acts 14:9)","The moment Paul said 'stand up,' leaping up and walking, an immediate response to God's word"],
 caution=[],
 applications=["Is there a 'never walked' area in your life that needs to hear God say: stand up?","Faith is not only inward, but a posture of life others can see","Stand up today and take that step"],
 prayer="Lord, You said to the lame man: stand up, and he leaped up. Where You say 'stand up' to me today, help me obey and walk at once. Amen."),
"亚拿女先知": dict(lesson="Faithfulness of waiting a lifetime for God's promise",
 summary="An eighty-four-year-old prophetess who, after being widowed, prayed and fasted in the temple day and night, and at once recognized the infant Jesus when He was brought to the temple, proclaiming Him to all.",
 witness="She was widowed many years, never leaving the temple, fasting and praying night and day, serving God. Seventy years of waiting. Then at eighty-four, the one she awaited finally appeared—she saw the infant Jesus, at once thanked God, and spoke of the child to all. Long waiting is not waste, but accumulation.",
 follow=["Widowed for decades, at eighty-four still 'fasting and praying night and day in service to God,' waiting for the Messiah with the whole of her remaining life (Luke 2:37)","Recognizing the infant the moment He was brought into the temple, at once thanking God and proclaiming Him to all who waited for redemption (Luke 2:38)"],
 caution=[],
 applications=["What are you waiting on God for? Is your waiting active service or passive idleness?","Seventy years of service for one moment of witness—worth it?","Serve actively in your waiting today"],
 prayer="Lord, Anna waited seventy years, serving in the temple night and day, then saw You. Help me not waste my waiting, but use the time to serve You night and day. Amen."),
"西面（圣殿老人）": dict(lesson="Waiting for God's promise until you see it with your own eyes",
 summary="A righteous and devout old man to whom the Spirit revealed he would not die before seeing the Lord's Christ; when the infant Jesus was brought, he held Him and said: now I can depart in peace.",
 witness="He did not know how long he would wait, but he knew God's promise would surely come to pass. When the day came, he held the infant Jesus and said: Lord, now You let Your servant depart in peace, according to Your word. The end of waiting is fulfillment. He waited a lifetime for this one moment, then said: enough, I can go.",
 follow=["'Righteous and devout, waiting for the consolation of Israel,' waiting for the promise by the Spirit's guidance (Luke 2:25)","The moment he took up the infant Jesus, saying with a satisfied heart 'Lord, now You let Your servant depart in peace according to Your word' (Luke 2:29)"],
 caution=[],
 applications=["Do you have a special promise from God? Are you in waiting?","Waiting is not idleness, but living in the present by faith","When God's promise is fulfilled that day, what will you say?"],
 prayer="Lord, Simeon waited for Your promise, then said: enough, I can depart in peace. Help me have the same faith in waiting, knowing Your promise will surely come to pass. Amen."),
"亚哈随鲁王": dict(lesson="Power is overturned in God's hands",
 summary="King of Persia, the backdrop monarch of Esther; at first he rashly deposed his queen and was manipulated by Haman, but finally, under Esther's wisdom and God's sovereignty, became an instrument to save the Jews.",
 witness="He was a great emperor, but nearly all his decisions were influenced by others—first manipulated by Haman, then changed by Esther's wisdom. Scripture gives him no clear spiritual evaluation, yet each of his key decisions served God's plan under His sovereignty. God can use anyone—even one who does not know he is being used.",
 follow=["Making a just decision under Esther's right guidance"],
 caution=["Rashly manipulated by those around him into improper decisions","Power without wise guidance is dangerous"],
 applications=["Is there an Esther-like voice of wisdom around you? Do you heed it?","God can use anyone's decisions to accomplish His plan","Is your power used under right guidance?"],
 prayer="Lord, You reigned in King Ahasuerus' decisions, even though he did not know You. Thank You that Your sovereignty surpasses human power. Help me be a voice conveying Your wisdom, not a manipulating force. Amen."),
"以利户": dict(lesson="Young passion and limited insight",
 summary="A young man who appeared after Job's three friends, angry that the three elders could not answer Job, who defended God with many words, and was finally passed over by God without comment.",
 witness="He waited long before speaking, deferring to elders because of his youth. His starting point was zeal for God—he sincerely wanted to defend God. But his words were many, and in the end God mentioned only Job and the three friends, not him. Zeal without humility, many words yet off the mark. Young zeal needs time and suffering to mature.",
 follow=["The humility of waiting for the elders to speak first","Sincere zeal for God is a good starting point"],
 caution=["Speaking many words yet not truly helping the sufferer","Replacing real listening and empathy with passion"],
 applications=["When you speak, are you explaining or truly helping?","Passion is a good start, but not the end","Say one fewer thing today, and listen one more time"],
 prayer="Lord, Elihu was passionate yet was passed over by You. Help my passion not be merely speaking much, but truly listening, truly empathizing, and saying what You truly want said. Amen."),
"利亚": dict(lesson="Seeking God when unloved",
 summary="The wife Jacob did not love, who yet bore him sons one after another; Scripture describes each of her childbirths as a conversation with God, and she was finally buried in Abraham's family tomb.",
 witness="At her first son she said: the LORD has seen my affliction. At her third son she said: this time I will praise the LORD. She turned pain into pouring out to God; amid Jacob's neglect, God kept seeing her. Being overlooked by people is not being forgotten by God—God regards those marginalized by people.",
 follow=["Turning to God in a situation of being unloved","Conversing with God through every experience of life"],
 caution=["Jealous rivalry with her sister dragging down family relationships"],
 applications=["Do you feel unvalued in some relationship? God sees you too","Turn pain into prayer rather than bitterness","'This time I will praise the LORD'—find a reason for gratitude in pain"],
 prayer="Lord, Leah still turned to You while unloved. Help me, when overlooked, remember Your eyes always see me, turning every pain into an occasion to pour out to You. Amen."),
"拉结": dict(lesson="The struggle of deep love and the pain of barrenness",
 summary="The wife Jacob deeply loved, long barren, who finally bore Joseph and died in childbirth bearing Benjamin—becoming the deepest mother figure in Israel's emotional memory.",
 witness="Her tears and waiting were real. God finally heard her and opened her womb, and she bore Joseph. But she was not satisfied; she kept longing, and finally died bearing her second son. The prophet Jeremiah quoted her weeping to describe Israel's grief in exile: Rachel weeping for her children, refusing to be comforted. Her image became a symbol of mother-love through the generations.",
 follow=["Loving deeply, truly waiting on God","Still trusting and moving forward after receiving what she asked"],
 caution=["Envying her sister, saying: give me children, or I'll die","Stealing her father's household idols, bringing trouble"],
 applications=["Is there something you long for as desperately as Rachel? Bring it to God","Deep love is God's gift, but must not become an idol","Even in her waiting, God remembered her"],
 prayer="Lord, You saw Rachel's waiting and tears. Help me honestly bring my deepest longings to You, trusting Your timing in waiting, rather than replacing waiting with envy and grasping. Amen."),
}
